// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address newOwner) public {
        // The reference permits every address as newOwner; the zero address is the only forbidden one.
        vm.assume(newOwner != address(0));

        bool ok = true;
        vm.prank(c.owner());
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.owner() == newOwner);
    }
}
